# Copied field by field when a department is given its own copy of the questionnaire in force.
QUESTION_FIELDS = (
    "qid", "text", "polarity", "weight", "is_knockout", "evidence_required", "answer_type", "evidence_options",
    "added_here", "allows_na", "accepts_supporting", "checks", "allowed_answers", "file_types", "max_files",
    "position",
)


def _free_label(Version, start: int) -> str:
    n = start
    while Version.objects.filter(label=f"v{n}").exists():
        n += 1
    return f"v{n}"


def give_roles(User, Department) -> None:
    """The built-in "admin" sign-in becomes the super user; any other reviewer an admin of every
    department (they see what they saw before). With no "admin" account (a server whose reviewers
    use their own emails), the reviewers who can sign in become super users instead, so someone can
    still manage accounts and departments and nobody loses anything they could do."""
    User.objects.filter(email="admin", role="reviewer").update(role="superuser")
    if not User.objects.filter(role="superuser", is_active=True).exists():
        promoted = User.objects.filter(role="reviewer", is_active=True, is_staff=False).update(role="superuser")
        if promoted:
            print(f"\n  No 'admin' account: {promoted} reviewer(s) made super user.")
    departments = list(Department.objects.order_by("pk"))
    for user in User.objects.filter(role="reviewer"):
        user.departments.set(departments)


def split(apps, schema_editor):
    """Nothing changes for anyone on the day this runs:

    - the built-in "admin" sign-in becomes the super user (it already sees and does everything);
    - any other reviewer becomes an admin of every department, so they see what they saw before;
    - every department gets its own copy of the questionnaire in force, identical to it, and the
      applications not yet submitted follow their department's copy (submitted ones keep theirs).
    """
    User = apps.get_model("cases", "User")
    Department = apps.get_model("cases", "Department")
    Version = apps.get_model("cases", "QuestionnaireVersion")
    Section = apps.get_model("cases", "QuestionSection")
    Question = apps.get_model("cases", "Question")
    Assessment = apps.get_model("cases", "Assessment")

    give_roles(User, Department)
    departments = list(Department.objects.order_by("pk"))

    # The questionnaire in force; failing that, the latest published (one is always seeded, 0003).
    shared = Version.objects.filter(department__isnull=True)
    current = shared.filter(is_active=True).order_by("-pk").first() or shared.order_by("-pk").first()
    if current is None:
        schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")
        return
    current.is_active = False
    current.save(update_fields=["is_active"])
    sections = list(Section.objects.filter(version=current).order_by("position"))
    questions = list(Question.objects.filter(version=current).order_by("position"))
    for department in departments:
        top = Version.objects.aggregate(n=models.Max("pk"))["n"] or 0
        copy = Version.objects.create(label=_free_label(Version, top + 1), is_active=True, department=department)
        copied = {
            s.pk: Section.objects.create(version=copy, name=s.name, weight=s.weight, position=s.position)
            for s in sections
        }
        Question.objects.bulk_create([
            Question(version=copy, section=copied[q.section_id], **{f: getattr(q, f) for f in QUESTION_FIELDS})
            for q in questions
        ])
        Assessment.objects.filter(stage="NOT_SUBMITTED", department=department).update(version=copy)
    # The rows above leave deferred foreign-key checks pending; PostgreSQL refuses to alter a table
    # while any are (the constraints added next), so they are checked now.
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


def unsplit(apps, schema_editor):
    """Back to one questionnaire for everyone: the one in force before (the departments' copies are
    kept, not in force, as cases may be held to them), and back to reviewers only."""
    User = apps.get_model("cases", "User")
    Version = apps.get_model("cases", "QuestionnaireVersion")
    Version.objects.filter(department__isnull=False).update(is_active=False)
    latest = Version.objects.filter(department__isnull=True).order_by("-pk").first()
    if latest is not None:
        Version.objects.filter(pk=latest.pk).update(is_active=True)
    User.objects.filter(role="superuser").update(role="reviewer")
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


